WHO = {'column': [('zecyfools', 30687), ('muefldum', 0), ('mulceflsof', 30879), ('zeecelldmicr', 31071), ('muefldum', 31583), ('renmaccuya', 31647), ('zecyfflsof', 31647), ('zecyfools', 0)], 'tree': [('mufools', 30943), ('zeeceeldmicr', 0), ('renmaelysen', 31647), ('thidu', 0), ('quhlyeben', 31903), ('brifofocren', 0), ('brifofocren', 32159), ('renmaelysen', 32159)], 'castle': [('zeeceeeyeben', 31263), ('zeeceelysen', 34082), ('zeeceeeyeben', 0), ('zeeceelysen', 45412)], 'bridge': [('psiloldmicr', 0), ('psiloldmicr', 0), ('psiloldmicr', 0), ('psiloldmicr', 0), ('alphafoldmicro', 44836)], 'manor': [('mueyffocren', 32607), ('thihepy', 34979), ('einsof', 35043), ('mueyffocren', 36899), ('eindmicro', 37411), ('mulcefldmicr', 37411), ('einsof', 42212), ('mueyffocren', 0)], 'tower': [('zeecefhlsof', 0), ('aprilcuya', 35747), ('zeecefldum', 36707), ('psiloceyeben', 37859), ('bridldmicro', 39331), ('zeecefhlsof', 0), ('zecyhepy', 42724), ('zeecefhlsof', 44836)], 'temple': [('aprilsof', 37603), ('eindmofel', 38435), ('zecyhepy', 0), ('aprillfldum', 41059)]}

EPI_RX = re.compile(
    r"^(?:what (?:has|have) (?P<a>[\w'\- ]{2,24}?) (?:done|been doing)"
    r"|what happened (?:with|to) (?P<b>[\w'\- ]{2,24}?))[?.! ]*$", re.I)
WHO_RX = re.compile(
    r"^who (?:built|made|raised) (?:a |an |the )?(?P<k>[\w \-]{2,24}?)[?.! ]*$", re.I)


class OracleReleaseRuntimeW325(OracleReleaseRuntimeW324):
    """Base + episodic recall. Fires only on bound episodes; else the chain answers."""

    def chat(self, text: str, session_id: str = "default") -> dict:
        s = " ".join(str(text).strip().split())
        m = EPI_RX.match(s)
        if m:
            actor = (m.group("a") or m.group("b") or "").strip().lower()
            eps = EPI.get(actor)
            if eps:
                bits = "; ".join(f"at tick {t} {v} {o}" for t, v, o in eps[-5:])
                pending = getattr(self, "_pending_conversion", None)
                if pending is None:
                    pending = self._pending_conversion = {}
                pending[session_id] = {"construction": "EPISODIC_RECALL",
                                        "from": s[:80], "to": f"episodes({actor})",
                                        "produced_by": "oracle_fold_worker_v4"}
                return {"status": "answered", "path": "worker:episodic",
                         "response": f"The record holds for {actor}: {bits}. "
                                     f"[world_ledger_ew2]",
                         "provenance": {"kind": "episodic_ledger", "actor": actor,
                                         "episodes": len(eps)},
                         "latency_ms": 1}
        w = WHO_RX.match(s)
        if w:
            kind = w.group("k").strip().lower()
            hits = WHO.get(kind) or WHO.get(kind.rstrip("s"))
            if hits:
                bits = ", ".join(f"{a} (tick {t})" for a, t in hits[-4:])
                return {"status": "answered", "path": "worker:episodic_who",
                         "response": f"By the world record, {kind}s were raised by "
                                     f"{bits}. [world_ledger_ew2]",
                         "provenance": {"kind": "episodic_ledger", "object": kind},
                         "latency_ms": 1}
        return super().chat(s, session_id)
